// Extrae sessionId y message del body del POST.
// sessionId identifica la sesion de memoria del usuario.
// Si no viene sessionId, genera uno automatico.
const raw = $input.first().json;
const body = raw.body || raw;

const sessionId = String(body.sessionId || '').trim()
  || 'sanos_' + Date.now() + '_' + Math.random().toString(36).substring(2, 8);

const chatInput = String(body.message || body.chatInput || '').trim();

if (!chatInput) throw new Error('El campo message es requerido');

return [{ json: { sessionId, chatInput } }];
